function validate([nums, target]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (target.length !== nums.length) return 'nums and target must have the same length.';
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] < 1 || nums[i] > 100000000 || target[i] < 1 || target[i] > 100000000) return 'Every value is between 1 and 10^8.';
  }
  return null;
}

