function minimumOperations(nums, target) {
  let operations = 0;
  let previous = 0;
  for (let i = 0; i < nums.length; i++) {
    const diff = target[i] - nums[i];
    if (diff > 0 && previous > 0) {
      operations += Math.max(0, diff - previous);
    } else if (diff < 0 && previous < 0) {
      operations += Math.max(0, previous - diff);
    } else {
      operations += Math.abs(diff);
    }
    previous = diff;
  }
  return operations;
}

