function minimumOperations(nums, target) {
  // Divide and conquer: across a run of gaps with the same sign, the smallest gap's worth of operations
  // can cover the whole run; remove them, then the run splits where gaps reach zero.
  const diff = nums.map((value, i) => target[i] - value);
  const stack = [[0, diff.length]];
  let total = 0;
  while (stack.length > 0) {
    const [lo, hi] = stack.pop();
    let i = lo;
    while (i < hi) {
      if (diff[i] === 0) {
        i++;
        continue;
      }
      const sign = Math.sign(diff[i]);
      let j = i;
      while (j < hi && Math.sign(diff[j]) === sign) j++;
      let least = Infinity;
      for (let k = i; k < j; k++) least = Math.min(least, Math.abs(diff[k]));
      for (let k = i; k < j; k++) diff[k] -= sign * least;
      total += least;
      stack.push([i, j]);
      i = j;
    }
  }
  return total;
}

