function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const mode = int(0, 2);
    const nums = [];
    const target = [];
    let gap = 0;
    for (let i = 0; i < n; i++) {
      if (mode === 0) {
        // Unrelated values: gaps of any size and sign.
        nums.push(int(1, 100000000));
        target.push(int(1, 100000000));
      } else if (mode === 1) {
        // Gaps follow a random walk, so long same-signed stretches share operations.
        gap = Math.max(-1000000, Math.min(1000000, gap + int(-50000, 50000)));
        const base = int(1000001, 99000000);
        nums.push(base);
        target.push(base + gap);
      } else {
        // Mostly equal already, with scattered differences.
        const base = int(1001, 99999000);
        nums.push(base);
        target.push(rand() < 0.1 ? base + int(-1000, 1000) : base);
      }
    }
    return [nums, target];
  }
  const n = int(1, 6);
  const top = int(1, 6);
  return [Array.from({ length: n }, () => int(1, top)), Array.from({ length: n }, () => int(1, top))];
}
